"""Shared helpers for the WP11 generators: Markdown tables and PRD lookups."""

from __future__ import annotations

import re
from collections.abc import Iterable, Sequence
from pathlib import Path
from typing import Any

from infra.paths import REPO_ROOT

DOCS_DIR = REPO_ROOT / "docs"
GENERATED_DIR = DOCS_DIR / "generated"
GENERATED_NOTE = (
    "> Generated by `python tasks.py docs` from the code ({source}). Do not edit by hand."
)


def mock_settings() -> Any:
    """Settings with ``LLM_BACKEND=mock`` whatever ``.env`` says: the demo, the evidence and
    the generated docs never call a model, so they stay free and byte-identical (AGT-22)."""
    from infra.settings import get_settings

    return get_settings().model_copy(update={"llm_backend": "mock"})


def cell(value: object) -> str:
    """One Markdown table cell: pipes escaped, newlines flattened."""
    return str(value).replace("|", "\\|").replace("\n", " ").strip()


def table(headers: Sequence[str], rows: Iterable[Sequence[object]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(cell(v) for v in row) + " |" for row in rows]
    return "\n".join(out) + "\n"


def write_md(path: Path, text: str) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text if text.endswith("\n") else text + "\n", encoding="utf-8", newline="\n")
    return path


_REG_ROW = re.compile(r"^\| (REG-[A-Z]+-\d+) \| (.+?) \|")


def regulation_names(prd14: Path | None = None) -> dict[str, str]:
    """``{"REG-ACC-01": "IFRS for SMEs Accounting Standard", ...}`` from PRD/14 §2: the
    bold name in the Source column (or its first clause)."""
    path = prd14 or REPO_ROOT / "PRD" / "14_regulatory.md"
    if not path.exists():
        return {}
    names = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        m = _REG_ROW.match(line)
        if not m:
            continue
        source = m.group(2)
        bold = re.search(r"\*\*(.+?)\*\*", source)
        name = bold.group(1) if bold else re.split(r"[(;.]", source)[0]
        names[m.group(1)] = name.strip()[:90]
    return names
